using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public static class SupportTests
{
 static int checks;
 static void Check(bool ok,string label){if(!ok)throw new Exception("SUPPORT FAIL: "+label);checks++;Console.WriteLine("SUPPORT PASS: "+label);}
 static SupportDefinition Def(string kind,int size=1)=>SupportCatalog.All.First(d=>d.Kind==kind&&(kind is "Sensor" or "Tracking" or "Ramp"||d.Size==size));
 static DemoWorld World(string hull="command") {var w=new DemoWorld();w.NewGame(0);w.SupportTrial(hull);w.Credits=100000;return w;}
 static SpaceTarget Target(DemoWorld w)
 {var p=new Ship();p.SetCombatHull("cruiser");var t=new SpaceTarget{Id="support_friend",Name="Test ally",Kind=TargetKind.Raider,Friendly=true,Training=true,Profile=p,Position=w.Player.Position+Vector3.UnitX*100,Shield=1,Armor=1,Hull=1,Cap=1,LockId=""};w.Targets.Add(t);w.SelectedId=w.LockedId=t.Id;return t;}
 static (DemoWorld w,SpaceTarget t,SupportState s) Ready(string kind,int size=1)
 {var d=Def(kind,size);var w=World(kind=="Ramp"?"adaptive_logistics":size==4?"titan":"command");Check(w.FitSupport(d.Id,true,d.Slot=="high"?0:6),"Prepare "+d.Name);var s=w.Player.Support[d.Slot=="high"?0:6];w.Undock();return(w,Target(w),s);}
 public static void Run()
 {
  Check(SupportCatalog.All.Length==33&&SupportCatalog.All.Select(d=>d.Id).Distinct().Count()==33,"33 unique logistics and command profiles");Check(SupportPayloads.New.Length==24,"19 burst charges plus five scripts");Check(SupportPayloads.New.Where(p=>p.Family=="Mining").All(p=>p.Bonuses.GetValueOrDefault("miningSurvey")==2),"Mining survey upgrade uses an assignment tier, not a percentage modifier");
  foreach(var d in SupportCatalog.All)
  {
   var w=World(d.Kind=="Ramp"?"adaptive_logistics":d.Size==4?"titan":"command");int slot=d.Slot=="high"?0:6;float stock=w.ItemCount(d.Id,true);Check(w.FitSupport(d.Id,true,slot),"Fit "+d.Name);var s=w.Player.Support[slot];Check(w.ItemCount(d.Id,true)==stock-1&&w.Player.Stat("cpuLoad")>=d.Cpu,"Stock / fitting budget "+d.Name);
   var payload=SupportPayloads.For(d).FirstOrDefault();if(payload!=null)Check(w.LoadSupportPayload(slot,payload.Id),"Load "+d.Name);
   Check(!w.ToggleSupport(slot),"Docked activation rejected "+d.Name);w.Undock();var t=Target(w);var p=w.Player;s.Repeat=false;s.AutoReload=false;float cap=p.Cap;int loaded=s.Loaded;
   Check(w.ToggleSupport(slot),"Activate "+d.Name);
   Check(p.Cap<cap||d.Kind=="AncShield"&&p.Cap==cap,"Paid cycle or fuel "+d.Name);
   if(d.Delayed){Check(t.Armor==1&&t.Hull==1&&s.PendingAmount>0,"Delayed start "+d.Name);w.UpdateSupport(d.Cycle+1);Check(d.Kind=="Hull"?t.Hull>1:t.Armor>1,"Delayed completion "+d.Name);}
   else if(d.Kind is "Shield" or "AncShield")Check(t.Shield>1,"Immediate remote shield "+d.Name);
   else if(d.Kind=="Cap")Check(t.Cap>1&&t.Cap<=t.Profile!.MaxCap,"Immediate bounded cap transfer "+d.Name);
   else if(d.Kind=="Burst")Check(p.SupportEffects.Any(e=>e.Burst&&e.Bonuses.Count>0)&&!t.Profile!.SupportEffects.Any(),"Burst reaches self; excludes non-fleet friendly "+d.Name);
   else Check(t.Profile!.SupportEffects.Any(e=>!e.Burst),"Live targeted link "+d.Name);
   if(payload?.Consumable==true)Check(s.Loaded<loaded,"Consumes real charge "+d.Name);
   w.Screen=ViewMode.Station;Check(w.UnfitSupport(slot)&&w.ItemCount(d.Id,true)==stock,"Module returned "+d.Name);
  }
  var small=World("frigate");Check(!small.FitSupport(Def("Shield",4).Id,true,0),"Capital restriction");Check(!small.FitSupport(SupportCatalog.All.First(d=>d.Kind=="Burst").Id,true,0),"Command hull restriction");Check(!small.FitSupport(Def("Ramp").Id,true,0),"Adaptive hull restriction");Check(!small.FitSupport(Def("Armor").Id,true,6),"Wrong socket");
  var shared=World();var rep=Def("Armor");for(int i=0;i<6;i++){shared.Hangar[rep.Id]=10;Check(shared.FitSupport(rep.Id,true,i),"Shared high rack fills "+i);}Check(!shared.FitDefense(DefenseCatalog.All.First(d=>d.Kind=="Nullifier").Id,true,0)&&!shared.FitEwar(EwarCatalog.All.First(d=>d.Kind==EwarKind.Neutralizer&&d.Size==1).Id,true,0),"Other families cannot exceed shared high sockets");
  var cpu=World();cpu.Player.SetStat("cpuOutput",44);float q=cpu.ItemCount(rep.Id,true);Check(!cpu.FitSupport(rep.Id,true,0)&&cpu.ItemCount(rep.Id,true)==q,"Budget rejection preserves stock");
  var anc=World();Check(anc.FitSupport(Def("AncShield").Id,true,0)&&!anc.FitSupport(Def("AncShield",2).Id,true,1),"Ancillary remote shield group limit");Check(!anc.LoadSupportPayload(0,"dc_800")&&anc.LoadSupportPayload(0,"dc_25"),"Remote ancillary chassis cell compatibility");
  foreach(var kind in new[]{"AncArmor","AncShield"})
  {var (w,t,s)=Ready(kind);s.Repeat=false;s.AutoReload=false;int slot=0;w.Player.Cap=0;Check(kind=="AncArmor"?!w.ToggleSupport(slot):!w.ToggleSupport(slot),"Dry ancillary still needs cap "+kind);w.Player.Cap=w.Player.MaxCap;w.ToggleSupport(slot);if(kind=="AncShield")Check(t.Shield>1,"Dry shield works with capacitor");else {w.UpdateSupport(s.Definition!.Cycle+1);Check(t.Armor>1,"Dry armor works with capacitor");}}
  var fuel=World();var asd=Def("AncShield");fuel.FitSupport(asd.Id,true,0);fuel.LoadSupportPayload(0,"dc_25");fuel.Undock();Target(fuel);fuel.Player.Cap=0;var fs=fuel.Player.Support[0];fs.Repeat=false;fs.AutoReload=false;Check(fuel.ToggleSupport(0)&&fuel.Player.Cap==0&&fs.Loaded==6,"Charged remote shield ignores cap cost");
  var paste=World();paste.FitSupport(Def("AncArmor",3).Id,true,0);paste.LoadSupportPayload(0,"dc_paste");var ps=paste.Player.Support[0];Check(ps.Loaded==ps.Definition!.ChargeUse*8,"Remote armor magazine contains eight charged cycles");paste.Undock();var pt=Target(paste);ps.Repeat=false;ps.AutoReload=false;ps.Loaded=1;paste.ToggleSupport(0);Check(Math.Abs(ps.PendingAmount-ps.Definition.Amount*(1+(ps.Definition.PasteMultiplier-1)/ps.Definition.ChargeUse))<.01f,"Partial paste scales repair bonus");
  var (stop,st,ss)=Ready("Armor");ss.AutoReload=false;stop.ToggleSupport(0);stop.ToggleSupport(0);stop.UpdateSupport(ss.Definition!.Cycle+1);Check(st.Armor>1&&!ss.Active,"Stopping completes paid armor cycle");
  var (loss,lt,ls)=Ready("Armor");ls.Repeat=false;loss.ToggleSupport(0);loss.LockedId="";loss.UpdateSupport(ls.Definition!.Cycle+1);Check(lt.Armor==1,"Lost lock discards pending remote repair");
  var (range,rt,rs)=Ready("Armor");rs.Repeat=false;range.ToggleSupport(0);rt.Position=range.Player.Position+Vector3.UnitX*(rs.Definition!.Optimal+rs.Definition.Falloff);range.UpdateSupport(rs.Definition.Cycle+1);Check(Math.Abs(rt.Armor-1-rs.Definition.Amount*.5f)<.02f,"Remote repair falloff uses completion distance");
  var (imp,it,is1)=Ready("Shield");it.Profile!.SetStat("remoteRepairImpedance",.5);is1.Repeat=false;imp.ToggleSupport(0);Check(Math.Abs(it.Shield-1-is1.Definition!.Amount*.5f)<.01f,"Remote repair impedance");
  var (ramp,rmt,rms)=Ready("Ramp");ramp.ToggleSupport(0);ramp.Player.Cap=ramp.Player.MaxCap;ramp.UpdateSupport(rms.Definition!.Cycle+.01f);Check(rms.Ramp>0&&rms.PendingAmount>rms.Definition.Amount,"Adaptive repair ramps on same target");ramp.ToggleSupport(0);ramp.UpdateSupport(rms.CycleLeft+.1f);Check(rms.Ramp==0,"Stopping resets adaptive ramp");
  foreach(var payload in SupportPayloads.New.Where(p=>!p.Consumable))
  {var w=World();var d=SupportCatalog.All.First(d=>d.Kind==payload.Family);w.FitSupport(d.Id,true,6);w.LoadSupportPayload(6,payload.Id);w.Undock();var t=Target(w);var s=w.Player.Support[6];s.Repeat=false;w.ToggleSupport(6);var e=t.Profile!.SupportEffects.Single();Check(e.Bonuses.Count==(payload.Mode=="Range"&&d.Kind=="Tracking"?2:1),"Script specialization "+payload.Name);Check(s.Loaded==1,"Reusable script "+payload.Name);w.UpdateSupport(d.Cycle+1);Check(t.Profile.SupportEffects.Count==0,"Link expires "+payload.Name);}
  foreach(var payload in SupportPayloads.New.Where(p=>p.Consumable))
  {
   var w=World("expedition_command");w.HireWingmate("Escort");var d=SupportCatalog.All.First(d=>d.Kind=="Burst"&&d.Family==payload.Family);w.FitSupport(d.Id,true,0);w.LoadSupportPayload(0,payload.Id);w.Undock();var ally=w.Targets.First(t=>t.Id==w.Wingmates[0].Id);ally.Position=w.Player.Position+Vector3.UnitX*100;var outside=Target(w);outside.Position=w.Player.Position+Vector3.UnitX*(d.Optimal+1);w.Player.Support[0].Repeat=false;w.ToggleSupport(0);
   Check(w.Player.SupportEffects.Any(e=>e.Key==payload.Id)&&ally.Profile!.SupportEffects.Any(e=>e.Key==payload.Id),"Fleet pulse recipients "+payload.Name);Check(!outside.Profile!.SupportEffects.Any(),"Outside / non-fleet excluded "+payload.Name);
   foreach(var key in payload.Bonuses.Keys)Check(Math.Abs(w.Player.SupportFactor(key)-1)>.00001,"Live bonus "+payload.Name+" / "+key);
   Check(w.SupportDockLock>0,"Burst docking interlock "+payload.Name);w.Dock();Check(!w.Docked,"Dock blocked during pulse cycle "+payload.Name);w.UpdateSupport(d.Cycle+1);Check(w.Player.SupportEffects.Count>0,"Bonus persists after firing cycle "+payload.Name);w.UpdateSupport(d.BurstDuration*3);Check(w.Player.SupportEffects.Count==0,"Finite bonus duration "+payload.Name);
  }
  var stack=new Ship();stack.SupportEffects=[new(){Key="charge",Burst=true,Left=20,Bonuses=new(){["maxTargetRange"]=.2f}},new(){Key="charge",Burst=true,Left=10,Bonuses=new(){["maxTargetRange"]=.1f}}];Check(Math.Abs(stack.SupportFactor("maxTargetRange")-1.2f)<.001,"Same burst uses strongest; no multiplication");stack.SupportEffects.Add(new(){Key="link",Left=10,Bonuses=new(){["maxTargetRange"]=.1f}});Check(stack.SupportFactor("maxTargetRange")>1.2f&&stack.SupportFactor("maxTargetRange")<1.32f,"Targeted and burst bonuses diminish together");
  var over=Ready("Armor");over.s.Overheat=true;over.s.Repeat=false;over.w.ToggleSupport(0);Check(over.s.Damage>0&&over.s.CycleLeft<over.s.Definition!.Cycle,"Overload output / cycle / condition");over.w.UpdateSupport(over.s.CycleLeft+.1f);over.w.Screen=ViewMode.Station;over.w.UnfitSupport(0);Check(over.w.HasDamagedSupportStock(over.s.ModuleId,true),"Condition survives unfit");over.w.FitSupport(over.s.ModuleId,true,0);Check(over.w.Player.Support[0].Damage>0,"Condition survives refit");Check(over.w.RepairSupport(0)&&over.w.Player.Support[0].Damage==0,"Paid station repair");
  var save=World();save.HireWingmate("Escort");save.FitSupport(Def("AncArmor").Id,true,0);save.LoadSupportPayload(0,"dc_paste");save.Undock();var allySave=save.Targets.First(t=>t.Id==save.Wingmates[0].Id);save.SelectedId=save.LockedId=allySave.Id;allySave.Armor=1;save.ToggleSupport(0);save.UpdateSupport(.3f);save.Save();var loadedWorld=new DemoWorld();Check(loadedWorld.Load(),"Support save load");Check(loadedWorld.Player.Support[0].Loaded==7&&loadedWorld.Player.Support[0].PendingAmount>0&&loadedWorld.Wingmates.Count==1,"Charges, paid cycle and fleet persist");loadedWorld.UpdateSupport(6);Check(loadedWorld.Targets.First(t=>t.Id==allySave.Id).Armor>1,"Pending repair completes after load");
  var travel=World();var bd=SupportCatalog.All.First(d=>d.Kind=="Burst"&&d.Family=="Armor");travel.FitSupport(bd.Id,true,0);travel.LoadSupportPayload(0,SupportPayloads.For(bd)[0].Id);travel.HireWingmate("Escort");travel.Undock();travel.ToggleSupport(0);travel.EnterGrid("belt");Check(travel.Player.SupportEffects.Count>0&&travel.Wingmates.Count==1,"Burst and fleet follow same-system warp");travel.EnterGrid(travel.SystemId+":gate:vale");travel.Player.Position=Microsoft.Xna.Framework.Vector3.Zero;Check(!travel.CanUseGate("player"),"Burst weapons timer blocks immediate gate transit");travel.UpdateSupport(60.1f);travel.Jump("vale");Check(travel.Player.SupportEffects.Count==0&&travel.Wingmates.Count==1,"System transit clears bonuses, keeps fleet");
  var capitalCycle=new Ship();capitalCycle.SupportEffects=[new(){Key="cadence",Burst=true,Left=60,Bonuses=new(){["armorCycle"]=-.2f,["shieldCycle"]=-.2f}}];Check(capitalCycle.RepairCadence("ArmorRepair",1)<1&&capitalCycle.RepairCadence("ArmorRepair",4)==1&&capitalCycle.RepairCadence("Armor",4,true)<1,"Cadence excludes capital local repairs; includes capital remote repairs");
  var logi=World("logistics");var caplink=Def("Cap");logi.FitSupport(caplink.Id,true,0);logi.Undock();var linkTarget=Target(logi);linkTarget.Position=logi.Player.Position+Vector3.UnitX*caplink.Optimal*3;float beforeCap=logi.Player.Cap;Check(logi.ToggleSupport(0)&&Math.Abs(beforeCap-logi.Player.Cap-caplink.Capacitor*.45f)<.02f&&linkTarget.Cap>1,"Logistics hull increases reach and reduces activation cost for viable cap links");
  var preserve=World();var prismStock=preserve.ItemCount("mining_focus",true);Check(preserve.LoadMiningFocus(true)&&preserve.ItemCount("mining_focus",true)==prismStock-1&&!preserve.LoadMiningFocus(true),"Mining prism uses inventory; cannot reset loaded wear");preserve.Player.SupportEffects=[new(){Key="preservation",Burst=true,Left=100,Bonuses=new(){["crystalWear"]=-.9f}}];var rock=new SpaceTarget{Kind=TargetKind.Asteroid,Ore=100000};for(int i=0;i<50;i++){preserve.Player.Ore=0;preserve.MiningHarvest(rock,14);}Check(preserve.Player.MiningFocusLoaded&&preserve.Player.MiningFocusWear<1,"Preservation bonus reaches live crystal wear probability");
  var precision=World();precision.Player.SupportEffects=[new(){Key="precision",Burst=true,Left=100,Bonuses=new(){["miningCrit"]=.45f,["miningResidue"]=-.135f,["miningRange"] = .36f,["miningCycle"]=-.135f,["miningCap"]=-.135f}}];Check(precision.Player.Stat("miningRange")>6500&&precision.Player.Stat("miningCycle")<4.8&&precision.Player.SupportFactor("miningCap")<1&&precision.Player.SupportFactor("miningCrit")>1&&precision.Player.SupportFactor("miningResidue")<1,"Mining command bonuses drive cycle, cap, reach, critical and residue mechanisms");
  var probeWorld=World();probeWorld.SystemId="umbra";var probe1=new ProbePuzzle();probe1.Analyze(probeWorld);int baseSignal=probe1.Signal;probeWorld.Player.SupportEffects=[new(){Key="expedition",Burst=true,Left=100,Bonuses=new(){["probeStrength"]=.15f,["probeDeviation"]=-.3f,["virusCoherence"]=.15f,["analyzerRange"]=.3f,["maxDirectionalScanRange"]=.3f}}];var probe2=new ProbePuzzle();probe2.Analyze(probeWorld);Check(probe2.Signal>baseSignal&&Vector2.Distance(probe2.Estimate,probe2.Secret)<Vector2.Distance(probe1.Estimate,probe1.Secret),"Expedition strength and precision reach real probe puzzle");var hack=new HackPuzzle();hack.Reset(probeWorld.Player);Check(hack.Coherence>65&&probeWorld.Player.SupportFactor("analyzerRange")>1&&probeWorld.Player.Stat("maxDirectionalScanRange")>2130000000000,"Expedition reach and coherence reach analyzer / directional stats");
  var salvage=World();salvage.Hangar["salvager"]=1;Check(salvage.FitItem("salvager",true),"Salvage beam fits utility high");salvage.Undock();salvage.Player.SupportEffects=[new(){Key="expedition",Burst=true,Left=100,Bonuses=new(){["salvageRange"]=.3f,["salvageCycle"]=-.2f}}];var wreck=new SpaceTarget{Id="support_wreck",Kind=TargetKind.Wreck,Salvage=3,SalvageDifficulty=-1,Position=salvage.Player.Position+Vector3.UnitX*6000};salvage.Targets.Add(wreck);salvage.SelectedId=salvage.LockedId=wreck.Id;Check(salvage.ToggleSalvager(),"Reach burst enables salvage beyond base range");salvage.Update(.05f);Check(salvage.SalvagerLeft>0&&salvage.SalvagerLeft<10,"Expedition precision shortens full salvage cycle");salvage.Update(8.1f);Check(salvage.ItemCount("salvage",false)==3&&wreck.Salvage==0,"Salvage cycle extracts finite contents");
  var hpWorld=World();hpWorld.Player.SupportEffects=[new(){Key="hp",Burst=true,Left=.1f,Bonuses=new(){["shieldCapacity"]=.2f}}];hpWorld.Player.Shield=hpWorld.Player.MaxShield*.5f;hpWorld.UpdateSupport(.2f);Check(Math.Abs(hpWorld.Player.Shield/hpWorld.Player.MaxShield-.5f)<.0001f,"Bonus expiry preserves buffer fraction");hpWorld.Player.SupportEffects=[new(){Key="hp",Burst=true,Left=20,Bonuses=new(){["shieldCapacity"]=.2f}}];hpWorld.Player.Shield=hpWorld.Player.MaxShield*.5f;hpWorld.LeaveSupportGrid(true);Check(Math.Abs(hpWorld.Player.Shield/hpWorld.Player.MaxShield-.5f)<.0001f,"Clearing transit buffs preserves buffer fraction");
  var inRange=World();inRange.HireWingmate("Escort");inRange.EnterSupportRange();Check(inRange.Targets.Any(t=>t.Id==inRange.Wingmates[0].Id),"Previously hired wingmate restored after range reconstruction");inRange.SupportPressure(inRange.Wingmates[0].Id);inRange.Player.Support[0]=SupportState.Create(Def("Shield").Id);inRange.SelectedId=inRange.LockedId=inRange.Wingmates[0].Id;Check(inRange.ToggleSupport(0)&&inRange.Targets.First(t=>t.Id==inRange.Wingmates[0].Id).Shield>220,"Range ally accepts a live support cycle");
  Console.WriteLine($"{checks} logistics and fleet support checks passed.");
 }
}
